CREATE OR REPLACE PROCEDURE sp(
    para_Start_year integer,
    para_Club_name text,
    para_Club_ID integer,
    para_Player_ID integer,
    para_Occupation text,
    para_Votes integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_min_start_year integer := para_Start_year;
    v_reference_player_id integer := COALESCE(para_Player_ID, 0);
BEGIN
    -- Phase 1
    UPDATE club
       SET Club_name = 'phase_1'
     WHERE Start_year >= v_min_start_year;
    DELETE FROM club
     WHERE Club_ID < para_Club_ID;
    UPDATE player
       SET Occupation = 'log_phase_1'
     WHERE Player_ID >= v_reference_player_id;
    DELETE FROM player
     WHERE Votes < para_Votes;

